css:
.site-footer .dv-section-0.dv-section{padding-top:100px;padding-bottom:54px;margin-top:0px;margin-bottom:0px}
.site-footer .dv-section.dv-section-1,.site-footer .dv-section.dv-section-2{background-size:initial;background-position:left top;background-image:linear-gradient(180deg,rgba(5,9,43,0.3) 0%,rgba(5,9,43,0.3) 100%),url(/uploads/2025-07-it-services-5-nyt-22-png.webp)!important}
.site-footer .dv-section-1.dv-section{padding-top:1px;padding-bottom:5px;margin-top:0px;margin-bottom:0px;background-color:#05092b!important}
.site-footer .dv-row-0{background-size:initial;background-position:right 0px top;background-image:url(/uploads/2025-07-it-services-5-nyt-23-png.webp),linear-gradient(94deg,#351ee0 0%,#3f74ef 100%);border-radius:5px 5px 5px 5px;overflow:hidden}
.site-footer .dv-row-0.dv-row{padding-top:60px!important;padding-right:60px!important;padding-bottom:60px!important;padding-left:60px!important;margin-top:-121px!important;margin-bottom:120px!important;padding-top:60px;padding-right:60px;padding-bottom:60px;padding-left:60px}
.site-footer .dv-row-0{width:90%;max-width:1290px}
.site-footer .dv-icon-0,.site-footer .dv-icon-1,.site-footer .dv-icon-2{text-align:center}
.site-footer .dv-icon-0 .dv-icon-wrap .dv-icon-glyph{font-weight:400!important;color:#FFFFFF;font-size:49px}
.site-footer .dv-text-0 h3,.site-footer .dv-text-2 h3,.site-footer .dv-text-4 h3{font-family:'Outfit',Helvetica,Arial,Lucida,sans-serif;font-size:23px;color:#FFFFFF!important;line-height:1.2em;text-align:left}
.site-footer .dv-text-0,.site-footer .dv-text-2,.site-footer .dv-text-4{padding-top:8px!important;padding-bottom:0px!important;margin-top:8px!important;margin-bottom:-4px!important}
.site-footer .dv-text-1.dv-text,.site-footer .dv-text-3.dv-text,.site-footer .dv-text-5.dv-text,.site-footer .dv-text-9.dv-text,.site-footer .dv-text-9.dv-text a{color:#FFFFFF!important}
.site-footer .dv-text-1,.site-footer .dv-text-3,.site-footer .dv-text-5{line-height:1.8em;font-family:'Plus Jakarta Sans',Helvetica,Arial,Lucida,sans-serif;font-size:15px;line-height:1.8em;padding-top:0px!important;padding-bottom:0px!important;margin-top:0px!important;margin-bottom:0px!important}
.site-footer .dv-icon-1 .dv-icon-wrap .dv-icon-glyph,.site-footer .dv-icon-2 .dv-icon-wrap .dv-icon-glyph{font-weight:900!important;color:#FFFFFF;font-size:49px}
.site-footer .dv-section-2.dv-section{padding-top:20px;padding-bottom:20px;margin-top:5px;margin-bottom:0px;background-color:#05092b!important}
.site-footer .dv-row-1{max-width:100%}
.site-footer .dv-image-0 .dv-image-wrap img{max-height:1000px;width:auto}
.site-footer .dv-image-0{width:100%;text-align:center}
.site-footer .dv-text-6 h3{font-weight:300;font-style:italic;font-size:18px;color:#FFFFFF!important;line-height:1.4em;text-align:center}
.site-footer .dv-text-6{border-bottom-color:#636363;margin-top:-7px!important;margin-bottom:12px!important}
.site-footer .dv-text-7 h3,.site-footer .dv-text-8 h3{font-weight:700;font-size:16px;color:#FFFFFF!important;line-height:1.4em}
.site-footer .dv-text-7,.site-footer .dv-text-8{border-bottom-width:2px;border-bottom-color:#636363;margin-bottom:12px!important}
.site-footer .dv-text-9{font-family:'Open Sans',Helvetica,Arial,Lucida,sans-serif}
.site-footer .dv-menu-0 .mobile_nav .mobile_menu_bar:before{color:#2ea3f2}
@media only screen and (min-width:981px){.site-footer .dv-row-1{width:84%}}
@media only screen and (max-width:980px){.site-footer .dv-section-0.dv-section{padding-top:120px;padding-bottom:0px}.site-footer .dv-section-1.dv-section,.site-footer .dv-section-2.dv-section{padding-top:1px;padding-bottom:120px}.site-footer .dv-row-0{background-color:initial}.site-footer .dv-row-0.dv-row{padding-top:80px!important;padding-right:60px!important;padding-bottom:80px!important;padding-left:60px!important;margin-top:-121px!important;margin-bottom:120px!important;padding-top:80px!important;padding-right:60px!important;padding-bottom:80px!important;padding-left:60px!important}.site-footer .dv-icon-0,.site-footer .dv-icon-1,.site-footer .dv-icon-2{margin-left:auto;margin-right:auto}.site-footer .dv-row-1{width:80%}.site-footer .dv-image-0 .dv-image-wrap img{width:auto}.site-footer .dv-text-6{border-bottom-color:#636363}.site-footer .dv-text-7,.site-footer .dv-text-8{border-bottom-width:2px;border-bottom-color:#636363}}
@media only screen and (max-width:767px){.site-footer .dv-section-0.dv-section{padding-top:90px;padding-bottom:0px}.site-footer .dv-section-1.dv-section,.site-footer .dv-section-2.dv-section{padding-top:1px;padding-bottom:90px}.site-footer .dv-row-0{background-image:linear-gradient(94deg,#351ee0 0%,#3f74ef 100%)}.site-footer .dv-row-0.dv-row{padding-top:60px!important;padding-right:40px!important;padding-bottom:60px!important;padding-left:40px!important;margin-top:-121px!important;margin-bottom:90px!important;padding-top:60px!important;padding-right:40px!important;padding-bottom:60px!important;padding-left:40px!important}.site-footer .dv-icon-0,.site-footer .dv-icon-1,.site-footer .dv-icon-2{margin-left:auto;margin-right:auto}.site-footer .dv-image-0 .dv-image-wrap img{width:auto}.site-footer .dv-text-6{border-bottom-color:#636363}.site-footer .dv-text-7,.site-footer .dv-text-8{border-bottom-width:2px;border-bottom-color:#636363}}
